  if (document.getElementById("log-table-body")) {
    initLogPage();
  }
  if (document.getElementById("copy-stats-btn") && document.getElementById("download-stats-btn")) {
    initColophonPage();
  }
  initCopyButtons();
  initPrint();
  initReportBrokenLink();
  initBadge();
})();
